-- Thread 1 (sort 282): wisdom-hidden-from-the-wicked-revealed-to-the-elect-in-1-enoch-and-2-esdras-and-wisdom
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'wisdom-hidden-from-the-wicked-revealed-to-the-elect-in-1-enoch-and-2-esdras-and-wisdom',
       'Wisdom hidden from the wicked and revealed to the elect — 1 Enoch 48, 2 Esdras 5, Wisdom of Solomon 1, and Sirach 39',
       'Matt 13:10-17''s parables-method and the Yeshayahu (Isaiah) 6:9-10 hardening-citation — *because it is given unto you to know the mysteries of the kingdom of heaven, but to them it is not given ... they seeing see not; and hearing they hear not, neither do they understand* — read against the wisdom-stream''s wisdom-hidden-from-the-wicked-revealed-to-the-elect architecture. Four moves: 1 Enoch 48:7 names the wisdom-of-the-Lord-of-Spirits revealed-to-the-holy-and-righteous; 2 Esdras (4 Ezra) 5:9-10 names the wisdom-and-understanding-withdrawing-into-the-secret-chamber and sought-of-many-and-not-found in the latter-days; Wisdom of Solomon 1:4 names THE direct verbal-anchor — *into a malicious soul wisdom shall not enter; nor dwell in the body that is subject unto sin*; Sirach (Ecclesiasticus) 39:6 names the spirit-of-understanding poured-out-on-the-elect-scribe when-the-great-Yahuah-wills. The framework reads the cluster as the wisdom-stream restatement of the cause-and-effect-of-hearing per Red Line #11: the giving precedes the hearing (the Greek *dedotai* at v.11 — passive perfect, *it has been given*); the disciples receive the mysteries because the disposition-to-receive has-been-given; the multitudes do-not-receive because the disposition-to-reject has-closed-the-soul. The wisdom-stream had named the architecture explicitly at the soul-disposition register; the King names the operative-form at the parables-method register. The Father does not actively-prevent the hearing; the disposition-closes-itself; the wisdom encounters-the-closure. The cause-and-effect-reversal Red Line #11 establishes — *if you hear, you are sons of Avraham (Abraham); you are sons of Adam* (you did not become these things by hearing; you heard because you are these things) — operates across both the wisdom-stream witnesses and the King''s parables-method.',
       sv.verse_id, ev.verse_id, 'complete_study', 282
  FROM _s143_verse_lookup sv, _s143_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 13 AND sv.verse_number = 10
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 13 AND ev.verse_number = 17
ON CONFLICT (slug) DO NOTHING;

-- Thread 2 (sort 283): birds-of-the-air-snatching-the-seed-mastema-and-the-watchers-in-jubilees-and-1-enoch
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'birds-of-the-air-snatching-the-seed-mastema-and-the-watchers-in-jubilees-and-1-enoch',
       'The birds-of-the-air snatching the seed as Mastema and the watchers'' work — Jubilees 11 and 1 Enoch 19',
       'Matt 13:4''s *fowls came and devoured them up* with the King''s-own-interpretation at Matt 13:19 (*then cometh the wicked one, and catcheth away that which was sown in his heart*) — read against the wisdom-stream''s direct articulation of the adversary-sending-birds-to-snatch-the-seed architecture. Two moves: Jubilees 11:11 names THE strongest direct verbal-anchor — *Prince Mastema sent ravens and birds to devour the seed which was sown in the land, in order to destroy the land, so as to rob the children of men of their labours. Before they could plough in the seed, the ravens picked it from the surface of the ground*; 1 Enoch 19:1 names the spirits-of-the-watchers leading-mankind-astray into sacrificing-to-demons-as-gods as the operative-mechanism. The framework reads the cluster as locking the framework''s reading of Matt 13:4-19 against any reading that treats the birds-of-the-air as neutral-wildlife. The fowls of Matt 13:4 are the wicked-one-of-Matt-13:19 in operative-form, the same Mastema-Satan-substance the wisdom-stream had named. The Avraham-driving-away-the-fowls at Bereshit (Genesis) 15:11 + the Jubilees 11:11 Mastema-sending-the-birds + the Matt 13:4-19 King''s-naming-the-wicked-one walk one architecture across the canon and the wisdom-stream. The framework reads the architecture in continuity with the mustard-seed parable''s birds-of-the-air lodging in the branches at vv.31-32 — the same fowl-substance carries through both parables, naming the corruption-pattern operating within the kingdom''s-visible-growth alongside the wheat.',
       sv.verse_id, ev.verse_id, 'complete_study', 283
  FROM _s143_verse_lookup sv, _s143_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 13 AND sv.verse_number = 4
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 13 AND ev.verse_number = 19
ON CONFLICT (slug) DO NOTHING;

-- Thread 3 (sort 284): seed-of-good-and-evil-sown-in-the-heart-of-adam-in-2-esdras
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'seed-of-good-and-evil-sown-in-the-heart-of-adam-in-2-esdras',
       'The seed of good and evil sown in the heart of Adam — 2 Esdras 4, 2 Esdras 3, and 2 Esdras 8',
       'Matt 13:24-30''s wheat-and-tares parable — *the kingdom of heaven is likened unto a man which sowed good seed in his field: But while men slept, his enemy came and sowed tares among the wheat, and went his way* — read against the wisdom-stream''s direct parallel of the seed-of-good-and-evil sown-in-the-heart-of-Adam architecture. Three moves: 2 Esdras (4 Ezra) 4:30 names THE direct wisdom-stream parallel — *the grain of evil seed hath been sown in the heart of Adam from the beginning, and how much ungodliness hath it brought up unto this time? and how much shall it yet bring forth until the time of threshing shall come?*; 2 Esdras 3:21-22 names the wicked-heart-inherited-from-Adam architecture — *the first Adam bearing a wicked heart transgressed, and was overcome; and so be all they that are born of him*; 2 Esdras 8:6 names the prayer-for-seed-unto-the-heart and culture-to-the-understanding so-that-fruit-may-come. The framework reads the cluster as the wisdom-stream''s direct restatement of the wheat-and-tares architecture at the heart-of-Adam register: the evil-seed was-sown-from-the-beginning AND the time-of-threshing-and-sorting-is-coming AND Yahuah-is-asked-for-seed-unto-the-heart that fruit-may-come. The King at Matt 13:24-30 names the operative-parable-form: the Sower sowing-good-seed in the field; the enemy sowing-tares-while-men-slept; the wheat-and-tares grow-together-until-the-harvest; the harvest-time the tares-burned-and-the-wheat-gathered. The framework reads the architecture WITHOUT collapsing into the Augustinian-original-sin doctrine in its Christian-developed-form: the framework preserves the actor''s-responsibility (the watchful-guard-fails per Matt 13:25''s *while men slept*) without erasing it; the wisdom-stream knew the inherited-heart-architecture without the Christian-doctrinal-overlay.',
       sv.verse_id, ev.verse_id, 'complete_study', 284
  FROM _s143_verse_lookup sv, _s143_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 13 AND sv.verse_number = 24
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 13 AND ev.verse_number = 30
ON CONFLICT (slug) DO NOTHING;

-- Thread 4 (sort 285): watchers-corruption-as-tares-sown-in-the-wheat-in-1-enoch-and-jubilees
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'watchers-corruption-as-tares-sown-in-the-wheat-in-1-enoch-and-jubilees',
       'The watchers'' corruption as tares sown in the wheat — 1 Enoch 6, 10, 15, and Jubilees 5, 7 (FRAMEWORK-MAJOR)',
       'Matt 13:25 and 13:38 — *while men slept, his enemy came and sowed tares ... the tares are the children of the wicked one; the enemy that sowed them is the devil* — read against the wisdom-stream''s direct articulation of the watchers'' incursion and the corrupted-line architecture. Five moves: 1 Enoch 6:1-6 names the watchers'' incursion — *the angels, the children of the heaven, saw and lusted after them, and said to one another: Come, let us choose us wives from among the children of men and beget us children*; 1 Enoch 10:9 names the children-of-the-watchers as *the bastards and the reprobates ... children of fornication* — a paternal-source-distinguishable-people; 1 Enoch 15:8-9 names the spirits-of-the-giants as *evil spirits upon the earth* operating-on-the-earth as the operative-instruments of the wicked-one''s sowing across the age; Jubilees 5:1-2 corroborates the watchers'' incursion at the second-witness register — *the angels of Yahuah saw them and took themselves wives of all whom they chose, and they bare unto them sons and they were giants*; Jubilees 7:21-22 names the multiple-corrupted-lineages (Naphidim, Naphil, Eljo) from the watchers'' fornication. The framework reads the cluster as FRAMEWORK-MAJOR for the Red Line #11 seed-war architecture: the wisdom-stream had named the children-of-the-watchers as a paternal-source-distinguishable-people; the King at Matt 13:25, 38 names the operative-form of the children-of-the-wicked-one as a paternal-source-distinguishable-people-within-the-field-of-the-world. The seed-distinction operates at the paternal-source level; the watchers'' incursion at Bereshit (Genesis) 6:1-4 produces a corrupted-line + corrupted-spirits operating-within-the-field-of-the-world as the seed-of-the-wicked-one alongside the seed-of-Adam. Two wisdom-stream witnesses (1 Enoch AND Jubilees) establish the substance the King''s parable names; the framework reads the architecture WITHOUT collapsing into the racial-determinism that the Black-Hebrew-Israelite-movement and various-other-systems have produced — the seed-distinction is real BUT operates within every people, not categorically along ethnic-lines; the harvest is the sorting; the present-age cannot finally-determine the sort by visible-criteria.',
       sv.verse_id, ev.verse_id, 'complete_study', 285
  FROM _s143_verse_lookup sv, _s143_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 13 AND sv.verse_number = 24
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 13 AND ev.verse_number = 43
ON CONFLICT (slug) DO NOTHING;

-- Thread 5 (sort 286): binding-the-watchers-at-the-day-of-judgment-with-fire-in-1-enoch
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'binding-the-watchers-at-the-day-of-judgment-with-fire-in-1-enoch',
       'Binding the watchers at the day of judgment with fire — 1 Enoch 10, 54, and 90',
       'Matt 13:30, 41-42 — *gather ye together first the tares, and bind them in bundles to burn them ... the Son of Adam shall send forth his angels, and they shall gather out of his kingdom all things that offend, and them which do iniquity; And shall cast them into a furnace of fire: there shall be wailing and gnashing of teeth* — read against the wisdom-stream''s direct articulation of the eschatological-binding-and-burning-of-the-watchers architecture. Three moves: 1 Enoch 10:13-14 names *they shall be led off to the abyss of fire: and to the torment and the prison in which they shall be confined for ever*; 1 Enoch 54:6 names THE direct verbal-anchor — *Mikha''el (Michael), and Gavri''el (Gabriel), and Raphael, and Phanuel shall take hold of them on that great day, and cast them on that day into the burning furnace*; 1 Enoch 90:25 names the seventy-shepherds-judged and *cast into an abyss, full of fire and flaming, and full of pillars of fire* (in the animal-apocalypse register). The framework reads the cluster as the wisdom-stream restatement of the eschatological-judgment-architecture the King''s wheat-and-tares-interpretation names. The reapers-are-the-angels of v.39 + the gathering-out-of-his-kingdom-all-things-that-offend of v.41 + the casting-into-the-furnace-of-fire of v.42 all operate in the architecture the wisdom-stream had named with specific-archangelic-naming and specific-abyss-of-fire-language. The framework reads this in continuity with the S142 thread (binding-of-the-watchers-typological-anchor-for-binding-the-strong-man at Matt 12:29) — the inaugurated-binding at the King''s present-age-ministry is the same architecture as the eschatological-final-binding-and-burning at the harvest; the present chapter''s wheat-and-tares parable names the final-binding-and-burning the inaugurated-binding-of-the-strong-man at Matt 12:29 anticipates.',
       sv.verse_id, ev.verse_id, 'complete_study', 286
  FROM _s143_verse_lookup sv, _s143_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 13 AND sv.verse_number = 41
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 13 AND ev.verse_number = 42
ON CONFLICT (slug) DO NOTHING;

-- Thread 6 (sort 287): righteous-shall-shine-as-the-sun-in-1-enoch-and-2-esdras-and-wisdom
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'righteous-shall-shine-as-the-sun-in-1-enoch-and-2-esdras-and-wisdom',
       'The righteous shall shine as the sun in the kingdom of their Father — 1 Enoch 104, 2 Esdras 7, and Wisdom of Solomon 3 (FRAMEWORK-MAJOR)',
       'Matt 13:43''s *then shall the righteous shine forth as the sun in the kingdom of their Father* read against the wisdom-stream''s direct articulation of the righteous-shining-as-the-sun-and-as-the-stars architecture. Four moves: 1 Enoch 104:2 names THE direct verbal-anchor — *now shall ye shine as the lights of heaven, ye shall shine and ye shall be seen, and the portals of heaven shall be opened to you*; 2 Esdras (4 Ezra) 7:97 names *the sixth order, when it is shewed them how their face shall shine as the sun, and how they shall be made like unto the light of the stars, being henceforth incorruptible*; 2 Esdras 7:125 names *the faces of them which have used abstinence shall shine above the stars*; Wisdom of Solomon 3:7 names *in the time of their visitation they shall shine, and run to and fro like sparks among the stubble.* The framework reads the cluster as FRAMEWORK-MAJOR for the eschatological-vindication architecture of the gathered-and-sifted-wheat: the wisdom-stream had named the architecture-of-the-righteous-shining at the resurrection-orders register, the abstinent-righteous register, AND the visitation-of-the-righteous register; the King at Matt 13:43 names the operative-form at the wheat-and-tares-interpretation register. Three wisdom-stream witnesses + the Tanakh-anchor at Daniel 12:3 (*they that be wise shall shine as the brightness of the firmament*) establish the substance the King''s parable interpretation names. The framework reads the architecture in continuity with the post-harvest-sifting per Red Line #11: the gathered-wheat that has-borne-fruit and survived the rod-of-Yechezk''el (Ezekiel) 20:37-38 shines-as-the-sun in the kingdom of the Father; the sparks-among-the-stubble of Wisdom 3:7 carries the harvest-and-burning imagery directly — the same harvest the King''s parable names, with the righteous-shining-as-sparks-among-the-burning-tares at the day of separation.',
       sv.verse_id, ev.verse_id, 'complete_study', 287
  FROM _s143_verse_lookup sv, _s143_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 13 AND sv.verse_number = 43
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 13 AND ev.verse_number = 43
ON CONFLICT (slug) DO NOTHING;

-- Thread 7 (sort 288): mysteries-hidden-from-the-foundation-revealed-to-the-elect-in-1-enoch-and-wisdom-and-2-esdras
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'mysteries-hidden-from-the-foundation-revealed-to-the-elect-in-1-enoch-and-wisdom-and-2-esdras',
       'Mysteries hidden from the foundation of the world revealed to the elect — 1 Enoch 46, 1 Enoch 48, Wisdom of Solomon 6, and 2 Esdras 6',
       'Matt 13:34-35''s *all these things spake Yahusha (Jesus) unto the multitude in parables ... That it might be fulfilled which was spoken by the prophet, saying, I will open my mouth in parables; I will utter things which have been kept secret from the foundation of the world* (citing Psalm 78:2) — read against the wisdom-stream''s direct articulation of the mysteries-hidden-from-the-foundation revealed-to-the-elect architecture. Four moves: 1 Enoch 48:6 names THE direct verbal-anchor for the Elect-One *hidden before him, before the creation of the world and for evermore* and revealed at the appointed-time; 1 Enoch 46:3 names the Son-of-Adam as the One-who-reveals-the-treasures-of-that-which-is-hidden — *this is the Son of Adam who hath righteousness, with whom dwelleth righteousness, and who reveals all the treasures of that which is hidden*; Wisdom of Solomon 6:22 names *as for wisdom, what she is, and how she came up, I will tell you, and will not hide mysteries from you*; 2 Esdras (4 Ezra) 6:26-28 names the latter-days when *the truth, which hath been so long without fruit, shall be declared.* The framework reads the cluster as the wisdom-stream restatement of the mysteries-secret-from-the-foundation-revealed-by-the-Son-of-Adam architecture: the wisdom-stream had named the architecture explicitly at the Elect-One register AND at the wisdom-teacher register; the King at Matt 13:34-35 names the operative-form of the architecture in his own parables-method. The Sower-of-the-good-seed of v.37 IS the Son-of-Adam the wisdom-stream had named as the Revealer-of-the-hidden-treasures; the parables-method is the operative-form of the office; the disciples-receive-the-revealing because they have-been-given-to-receive (per the cause-and-effect of Red Line #11 the Yeshayahu (Isaiah) 6:9-10 citation at vv.13-15 has just established).',
       sv.verse_id, ev.verse_id, 'complete_study', 288
  FROM _s143_verse_lookup sv, _s143_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 13 AND sv.verse_number = 34
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 13 AND ev.verse_number = 35
ON CONFLICT (slug) DO NOTHING;

-- Thread 8 (sort 289): kingdom-of-supreme-worth-treasure-and-pearl-in-sirach-and-wisdom-of-solomon
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'kingdom-of-supreme-worth-treasure-and-pearl-in-sirach-and-wisdom-of-solomon',
       'The kingdom of supreme worth as treasure and pearl — Sirach 6, Sirach 20, Wisdom of Solomon 7',
       'Matt 13:44-46''s hidden-treasure-and-pearl-of-great-price parables — *the kingdom of heaven is like unto treasure hid in a field ... the kingdom of heaven is like unto a merchant man, seeking goodly pearls* — read against the wisdom-stream''s direct articulation of the supreme-worth treasure-and-finding-of-incomparable-substance architecture. Four moves: Sirach (Ecclesiasticus) 20:30 names *wisdom that is hid, and treasure that is hoarded up, what profit is in them both?* (the hidden-treasure substance and the finding-and-using-it imperative); Sirach 6:14-15 names *a faithful friend is a strong defence: and he that hath found such an one hath found a treasure ... nothing doth countervail a faithful friend, and his excellency is invaluable* (the supreme-worth and incomparable-value substance); Wisdom of Solomon 7:8-9 names *I preferred her before sceptres and thrones, and esteemed riches nothing in comparison of her ... all gold in respect of her is as a little sand* (the wisdom-preferred-above-all-else); Wisdom of Solomon 7:14 names *she is a treasure unto men that never faileth.* The framework reads the cluster as the wisdom-stream restatement of the supreme-worth-substance the King''s parables name. Short.md walks the framework''s preferred reading: the Father-Son-buyer-finds-the-treasure substance — the Sower of vv.36-43 is the Son of Adam; the field is the world; the treasure-hid-in-the-field is the elect-treasure scattered through the field-of-the-world; the buyer is the Father / the Son who finds-and-rejoices-and-pays-the-full-price-to-obtain (per Isaiah 43:4 + Philippians 2:6-8). The framework reads the wisdom-stream cluster in continuity with the framework''s preferred reading: the supreme-worth-of-the-treasure operates at every register from the wisdom-stream through the King''s parables; the Father-Son-buyer-finds-the-elect-treasure preserves the cause-and-effect Red Line #11 established at vv.10-17 (the Father finds the elect; the elect did-not-find-the-Father-by-their-own-initiative; the kingdom-citizens'' supreme-prioritization-of-the-kingdom is the response-substance flowing from the belonging-already-conferred, not the causal-mechanism of the belonging).',
       sv.verse_id, ev.verse_id, 'complete_study', 289
  FROM _s143_verse_lookup sv, _s143_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 13 AND sv.verse_number = 44
