-- Thread 9 (sort 290): wheat-from-chaff-and-righteous-from-wicked-at-the-day-of-separation-in-2-esdras-and-1-enoch-and-wisdom
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'wheat-from-chaff-and-righteous-from-wicked-at-the-day-of-separation-in-2-esdras-and-1-enoch-and-wisdom',
       'Wheat from chaff and righteous from wicked at the day of separation — 2 Esdras 7, 2 Esdras 8, 1 Enoch 100, and Wisdom of Solomon 3',
       'Matt 13:47-50''s dragnet-parable — *the kingdom of heaven is like unto a net, that was cast into the sea, and gathered of every kind: Which, when it was full, they drew to shore, and sat down, and gathered the good into vessels, but cast the bad away. So shall it be at the end of the world: the angels shall come forth, and sever the wicked from among the just* — read against the wisdom-stream''s direct articulation of the wheat-from-chaff-and-righteous-from-wicked-at-the-day-of-separation architecture. Four moves: 2 Esdras (4 Ezra) 7:33-35 names *the most High shall appear upon the seat of judgment, and misery shall pass away, and the long suffering shall have an end: But judgment only shall remain*; 2 Esdras 8:3 names THE direct verbal-anchor — *many be created, but few shall be saved*; 1 Enoch 100:5 names *over all the righteous and holy he will appoint guardians from amongst the holy angels to guard them as the apple of an eye, until he makes an end of all wickedness and all sin*; Wisdom of Solomon 3:8 names *they shall judge the nations, and have dominion over the people.* The framework reads the cluster as the wisdom-stream restatement of the eschatological-separation the dragnet-parable recapitulates. The wheat-and-tares-interpretation at vv.36-43 named the architecture; the dragnet-parable at vv.47-50 recapitulates it from the sea-and-net angle; the wisdom-stream had named the architecture at multiple registers (the most-High-on-the-seat-of-judgment AND the few-saved-architecture AND the angelic-guardians AND the righteous-judge-the-nations). The framework reads this in continuity with the kingdom-of-priests destination-of-the-gathered-remnant per Red Line #7: the righteous-judge-and-rule the nations-left-after-the-judgment at the millennial-reign; the wisdom-stream and the gospel walk one architecture from the day-of-separation through the millennial-reign of the gathered-remnant ministering as priests to the nations.',
       sv.verse_id, ev.verse_id, 'complete_study', 290
  FROM _s143_verse_lookup sv, _s143_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 13 AND sv.verse_number = 47
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 13 AND ev.verse_number = 50
ON CONFLICT (slug) DO NOTHING;

-- Thread 10 (sort 291): seed-war-from-genesis-3-and-the-devil-as-source-of-death-in-wisdom-and-jubilees-and-1-enoch
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'seed-war-from-genesis-3-and-the-devil-as-source-of-death-in-wisdom-and-jubilees-and-1-enoch',
       'The seed-war from Genesis 3 forward with the devil as source of death — Wisdom of Solomon 2:24, 1 Enoch 22, and Jubilees 4 (FRAMEWORK-MAJOR)',
       'Matt 13:38-39''s *the good seed are the children of the kingdom; but the tares are the children of the wicked one; The enemy that sowed them is the devil* — read against the wisdom-stream''s direct articulation of the seed-war-from-Bereshit (Genesis)-3-forward-with-the-devil-as-source-of-death architecture. Three moves: Wisdom of Solomon 2:24 names THE direct verbal-anchor — *through envy of the devil came death into the world: and they that do hold of his side do find it* (the devil-as-source-of-death entering-the-world; they-that-hold-of-his-side find-death — the architecture the children-of-the-wicked-one operate within); 1 Enoch 22:5-7 names the spirits-of-the-dead separated-into-four-divisions with the spirit-of-Hevel (Abel) crying-out-against-Qayin (Cain) as the seed-war''s first-victim-crying-for-vindication; Jubilees 4:2 names the wisdom-stream restatement of the Bereshit (Genesis) 4 architecture — *Qayin (Cain) slew Hevel (Abel) because (God) accepted the sacrifice of Hevel (Abel), and did not accept the offering of Qayin (Cain) ... and his blood cried from the ground to heaven.* The framework reads the cluster as FRAMEWORK-MAJOR for the Red Line #11 seed-war architecture: the wisdom-stream identifies the devil as the source-of-death-and-corruption from the beginning (the serpent of Bereshit 3 + the envy that brings death into the world); the wisdom-stream identifies Qayin (Cain) as the seed-war''s first-fruit of the children-of-the-wicked-one (corroborated by 1 Yochanan (John) 3:12''s *not as Qayin (Cain), who was of that wicked one, and slew his brother*); the wisdom-stream identifies Hevel (Abel) as the first-victim of the architecture. The King at Matt 13:38-39 names the operative-form of the architecture the wisdom-stream had named at the foundational register. The architecture operates from Bereshit (Genesis) 3 forward through the field-of-the-world to the harvest; the devil''s envy at Bereshit 3 + the devil''s seduction at the watchers (1 Enoch 6-11) + the devil''s sowing-of-tares at Matt 13:39 = one architecture of the source-of-death-and-corruption across the canon and the wisdom-stream.',
       sv.verse_id, ev.verse_id, 'complete_study', 291
  FROM _s143_verse_lookup sv, _s143_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 13 AND sv.verse_number = 38
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 13 AND ev.verse_number = 39
ON CONFLICT (slug) DO NOTHING;

